347		}
348		if !slicesContains(resp.TransferEncoding, "chunked") {
349			t.Errorf("flush: expected chunked transfer encoding, got %v", resp.TransferEncoding)
350		}
351		if got := body(resp); got != "flush-body" {
352			t.Errorf("flush: expected body 'flush-body', got %q", got)
353		}
