365			resp = do(http.MethodGet, "http://localhost:9080/plain", nil)
366			if got := body(resp); got != "oldbody" {
367				t.Fatalf("alternate plain: expected body 'oldbody', got %q", got)
368			}
369			if resp.StatusCode != http.StatusOK {
370				t.Fatalf("alternate plain: expected status 200, got %d", resp.StatusCode)
371			}
372		}
373	}
374	
375	func slicesContains(s []string, v string) bool {
376		for _, item := range s {
377			if item == v {
378				return true
379			}
380		}
381		return false
382	}
