// replayTrailerVals re-attaches the original response's trailer
// values onto dst using the http.TrailerPrefix magic keys, so the
// net/http server emits them in the chunked trailer section rather
// than as regular response headers.
//
// Only fields still announced by dst's "Trailer" header are
// replayed, and any same-named values that were copied as regular
// headers are removed. For HEAD requests no values are attached:
// HEAD responses carry neither a body nor a trailer section, while
// the Trailer declaration and length semantics are left intact.
//
// EXPERIMENTAL: Subject to change or removal.
func replayTrailerVals(dst, orig http.Header, isHead bool) map[string][]string {
	announced := map[string]bool{}
	for _, decl := range dst.Values("Trailer") {
		for _, field := range strings.Split(decl, ",") {
			if field = strings.TrimSpace(field); field != "" {
				announced[http.CanonicalHeaderKey(field)] = true
			}
		}
	}

	vals := make(map[string][]string)
	for field := range announced {
		var vv []string
		vv = append(vv, orig[http.TrailerPrefix+field]...)
		vv = append(vv, orig[field]...)
		if len(vv) == 0 {
			continue
		}
		// the declared field names the original trailers occupy
		// are trailer space, never regular response headers
		dst.Del(field)
		vals[field] = vv
	}

	if isHead {
		return vals
	}
	for field, vv := range vals {
		dst[http.TrailerPrefix+field] = vv
		// trailers cannot share framing with a Content-Length;
		// chunking takes over (see chunkWriter in net/http)
		dst.Del("Content-Length")
	}
	return vals
}

